import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { GoogleGenAI, Modality } from '@google/genai';

interface TrollGameProps {
  isOpen: boolean;
  onClose: () => void;
}

const ROASTS = [
  "Teacher forgot your face",
  "Security thinks you’re a visitor",
  "Even WiFi attends more than you",
  "Bring parents tomorrow",
  "Attendance found in museum records",
  "You attend only on result day?",
  "HOD asks 'Who is this?'",
  "Your seat has been sold to a junior"
];

const LOADING_MSGS = [
  "Verifying with university server...",
  "Contacting HOD...",
  "Checking CCTV footage...",
  "Calculating bunk velocity...",
  "Analyzing excuses database..."
];

// Audio decoding helpers for Gemini PCM data
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const TrollGame: React.FC<TrollGameProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState<'form' | 'loading' | 'result'>('form');
  const [name, setName] = useState('');
  const [total, setTotal] = useState('');
  const [attended, setAttended] = useState('');
  const [examDate, setExamDate] = useState('');
  const [holidays, setHolidays] = useState(''); 
  const [loadingIndex, setLoadingIndex] = useState(0);
  const [isEligible, setIsEligible] = useState(false);
  const [percentage, setPercentage] = useState(0);
  const [roast, setRoast] = useState('');
  const [showFakeCall, setShowFakeCall] = useState(false);
  const [callStatus, setCallStatus] = useState<'incoming' | 'connected'>('incoming');
  const [medicalStatus, setMedicalStatus] = useState<'idle' | 'checking' | 'rejected'>('idle');
  const [medicalRejectReason, setMedicalRejectReason] = useState('');

  // Audio Refs
  const audioCtxRef = useRef<AudioContext | null>(null);
  const activeOscillatorsRef = useRef<any[]>([]);
  const ringtoneIntervalRef = useRef<number | null>(null);

  // Initialize Audio Context safely
  const initAudio = () => {
    if (!audioCtxRef.current) {
      const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
      if (AudioContextClass) {
          audioCtxRef.current = new AudioContextClass();
      }
    }
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  };

  const stopAllSounds = () => {
    // Stop all tracked oscillators and buffers
    activeOscillatorsRef.current.forEach(osc => {
        try {
            osc.stop();
            osc.disconnect();
        } catch(e) {}
    });
    activeOscillatorsRef.current = [];

    // Clear ringtone interval
    if (ringtoneIntervalRef.current) {
        clearInterval(ringtoneIntervalRef.current);
        ringtoneIntervalRef.current = null;
    }
  };

  const playSiren = () => {
     stopAllSounds();
     initAudio();
     const ctx = audioCtxRef.current;
     if(!ctx) return;

     const osc = ctx.createOscillator();
     const gain = ctx.createGain();

     osc.type = 'sawtooth';
     osc.frequency.setValueAtTime(600, ctx.currentTime);
     gain.gain.value = 0.1;

     const lfo = ctx.createOscillator();
     lfo.type = 'triangle';
     lfo.frequency.value = 2; 
     const lfoGain = ctx.createGain();
     lfoGain.gain.value = 200;

     lfo.connect(lfoGain);
     lfoGain.connect(osc.frequency);

     osc.connect(gain);
     gain.connect(ctx.destination);

     osc.start();
     lfo.start();

     activeOscillatorsRef.current.push(osc);
     activeOscillatorsRef.current.push(lfo);
  };

  const playSuccess = () => {
     stopAllSounds();
     initAudio();
     const ctx = audioCtxRef.current;
     if(!ctx) return;

     const playNote = (freq: number, time: number, duration: number) => {
         const osc = ctx.createOscillator();
         const gain = ctx.createGain();
         osc.type = 'sine';
         osc.frequency.value = freq;

         gain.gain.setValueAtTime(0.05, time);
         gain.gain.exponentialRampToValueAtTime(0.001, time + duration);

         osc.connect(gain);
         gain.connect(ctx.destination);
         osc.start(time);
         osc.stop(time + duration);
     };

     const now = ctx.currentTime;
     playNote(523.25, now, 0.5); 
     playNote(659.25, now + 0.1, 0.5); 
     playNote(783.99, now + 0.2, 0.8); 
     playNote(1046.50, now + 0.3, 1.5); 
  };

  const playRingtone = () => {
     stopAllSounds(); 
     initAudio();
     const ctx = audioCtxRef.current;
     if(!ctx) return;

     const playRing = () => {
         const now = ctx.currentTime;
         const osc1 = ctx.createOscillator();
         const osc2 = ctx.createOscillator();
         const gain = ctx.createGain();

         osc1.type = 'square';
         osc1.frequency.value = 800;
         osc2.type = 'square';
         osc2.frequency.value = 1000;

         gain.gain.setValueAtTime(0.05, now);
         gain.gain.linearRampToValueAtTime(0, now + 1.0);

         osc1.connect(gain);
         osc2.connect(gain);
         gain.connect(ctx.destination);

         osc1.start(now);
         osc1.stop(now + 1.0);
         osc2.start(now + 0.1); 
         osc2.stop(now + 1.0);

         activeOscillatorsRef.current.push(osc1, osc2);
     };

     playRing();
     ringtoneIntervalRef.current = window.setInterval(playRing, 2000);
  };

  const playErrorBuzz = () => {
      initAudio();
      const ctx = audioCtxRef.current;
      if(!ctx) return;

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.linearRampToValueAtTime(50, ctx.currentTime + 0.4);

      gain.gain.setValueAtTime(0.1, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.4);

      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.4);
  };

  const playHODVoice = async () => {
    initAudio();
    const ctx = audioCtxRef.current;
    if (!ctx) return;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Say strictly and with deep authority: "${name || 'Student'}, your attendance record is a total disaster. This is unacceptable. I want you in my office immediately after class. Do not be late."`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Charon' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const audioBuffer = await decodeAudioData(
          decode(base64Audio),
          ctx,
          24000,
          1
        );
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
        activeOscillatorsRef.current.push(source);
      }
    } catch (error) {
      console.error("Failed to generate HOD voice:", error);
    }
  };

  // Reset state when opening
  useEffect(() => {
    if (isOpen) {
      setStep('form');
      setMedicalStatus('idle');
      setShowFakeCall(false);
      setCallStatus('incoming');
      setName('');
      setTotal('');
      setAttended('');
      setExamDate('');
      setHolidays('');
      stopAllSounds();
    } else {
        stopAllSounds();
    }

    return () => stopAllSounds();
  }, [isOpen]);

  // Loading sequence
  useEffect(() => {
    if (step === 'loading') {
      const interval = setInterval(() => {
        setLoadingIndex(prev => (prev + 1) % LOADING_MSGS.length);
      }, 800);

      const timeout = setTimeout(() => {
        clearInterval(interval);
        const t = parseInt(total) || 0;
        const a = parseInt(attended) || 0;
        const pct = t === 0 ? 0 : (a / t) * 100;
        setPercentage(pct);

        const eligible = pct >= 75;
        setIsEligible(eligible);

        if (eligible) {
            playSuccess();
        } else {
            playSiren();
            setRoast(ROASTS[Math.floor(Math.random() * ROASTS.length)]);
            // Schedule fake call
            setTimeout(() => {
                setShowFakeCall(true);
                playRingtone();
            }, 3000);
        }
        setStep('result');
      }, 3500);

      return () => {
        clearInterval(interval);
        clearTimeout(timeout);
      }
    }
  }, [step, total, attended]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    initAudio(); 
    if (!total || !attended) return;
    setStep('loading');
  };

  const handleMedicalCertificate = () => {
    initAudio();
    setMedicalStatus('checking');
    setTimeout(() => {
        const reasons = ["Ink too fresh", "Doctor is your uncle", "HOD denied instantly", "Certificate used by 5 others"];
        setMedicalRejectReason(reasons[Math.floor(Math.random() * reasons.length)]);
        setMedicalStatus('rejected');
        playErrorBuzz();
    }, 1500);
  };

  const answerCall = async () => {
    initAudio();
    setCallStatus('connected');
    stopAllSounds(); 

    // Play the stern Gemini TTS voice
    await playHODVoice();

    setTimeout(() => {
        setShowFakeCall(false);
        setCallStatus('incoming');
    }, 7000);
  };

  const handleClose = () => {
    stopAllSounds();
    onClose();
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
       <motion.div 
         initial={{ opacity: 0 }} 
         animate={{ opacity: 1 }} 
         exit={{ opacity: 0 }}
         className="fixed inset-0 z-[100000] bg-black/90 flex items-center justify-center p-4 font-sans"
       >
         <button onClick={handleClose} className="absolute top-4 right-4 text-white/50 hover:text-white z-50">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
         </button>

         {step === 'form' && (
            <motion.div 
                initial={{ scale: 0.9, y: 20 }}
                animate={{ scale: 1, y: 0 }}
                className="bg-white rounded-lg shadow-2xl w-full max-w-md overflow-hidden relative z-50"
            >
                <div className="bg-blue-900 p-6 text-center border-b-4 border-yellow-500">
                    <h2 className="text-2xl font-bold text-white uppercase tracking-wider">University Portal</h2>
                    <p className="text-blue-200 text-xs mt-1">Examination Eligibility Check v2.4</p>
                </div>
                <form onSubmit={handleSubmit} className="p-8 space-y-4">
                    <div>
                        <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Student Name</label>
                        <input 
                            required
                            type="text" 
                            className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black transition-colors"
                            placeholder="Enter full name"
                            value={name}
                            onChange={e => setName(e.target.value)}
                        />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Total Classes</label>
                            <input 
                                required
                                type="number" 
                                className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black transition-colors"
                                placeholder="0"
                                value={total}
                                onChange={e => setTotal(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Attended</label>
                            <input 
                                required
                                type="number" 
                                className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black transition-colors"
                                placeholder="0"
                                value={attended}
                                onChange={e => setAttended(e.target.value)}
                            />
                        </div>
                    </div>
                    <div>
                        <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Exam Start Date</label>
                        <input 
                            type="date" 
                            className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black transition-colors"
                            value={examDate}
                            onChange={e => setExamDate(e.target.value)}
                        />
                    </div>
                     <div>
                        <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Holidays (Optional)</label>
                        <input 
                            type="text" 
                            className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black transition-colors"
                            placeholder="e.g. Diwali, Christmas"
                            value={holidays}
                            onChange={e => setHolidays(e.target.value)}
                        />
                    </div>

                    <button 
                        type="submit"
                        className="w-full bg-blue-800 hover:bg-blue-900 text-white font-bold py-4 rounded shadow-lg transform transition active:scale-95 flex justify-center items-center gap-2 mt-4"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                        CHECK ELIGIBILITY
                    </button>
                    <div className="text-center">
                        <p className="text-[10px] text-gray-400 uppercase">Secure Server Connection • SSL Encrypted • Official Use Only</p>
                    </div>
                </form>
            </motion.div>
         )}

         {step === 'loading' && (
            <div className="text-center text-white space-y-8 z-50">
                <div className="relative">
                    <div className="w-24 h-24 border-4 border-blue-500/30 border-t-blue-500 rounded-full animate-spin mx-auto"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                        <span className="text-2xl">🔒</span>
                    </div>
                </div>
                <div className="space-y-2">
                    <h3 className="text-2xl font-bold font-mono tracking-widest">PROCESSING...</h3>
                    <motion.p 
                        key={loadingIndex}
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="text-blue-300 font-mono text-sm"
                    >
                        {LOADING_MSGS[loadingIndex]}
                    </motion.p>
                </div>
            </div>
         )}

         {step === 'result' && isEligible && (
            <motion.div 
                initial={{ scale: 0.5, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="bg-green-600 text-white p-10 rounded-3xl text-center shadow-[0_0_100px_rgba(34,197,94,0.6)] relative overflow-hidden max-w-2xl w-full z-50"
            >
                {[...Array(30)].map((_, i) => (
                    <motion.div
                        key={i}
                        className="absolute w-2 h-2 bg-white rounded-full"
                        initial={{ 
                            x: Math.random() * 600 - 300, 
                            y: -200, 
                            opacity: 1 
                        }}
                        animate={{ 
                            y: 800, 
                            rotate: 360,
                            opacity: 0
                        }}
                        transition={{ 
                            duration: Math.random() * 2 + 2, 
                            repeat: Infinity, 
                            delay: Math.random() * 2 
                        }}
                        style={{ left: '50%' }}
                    />
                ))}

                <div className="relative z-10">
                    <div className="text-6xl mb-6 bounce">🎉</div>
                    <h2 className="text-5xl font-black mb-2 uppercase tracking-tighter">Eligible!</h2>
                    <div className="text-3xl font-bold mb-6 text-green-200">{percentage.toFixed(1)}%</div>
                    <p className="text-xl font-medium text-green-100 mb-8">Congratulations, responsible human.</p>
                    <div className="bg-white/20 border border-white/30 p-4 rounded-xl inline-block backdrop-blur-sm">
                        <p className="font-mono text-sm font-bold tracking-widest">HALL TICKET GENERATED</p>
                        <p className="text-xs opacity-75 mt-1">ID: {Math.random().toString(36).substr(2, 9).toUpperCase()}</p>
                    </div>
                </div>
            </motion.div>
         )}

         {step === 'result' && !isEligible && (
            <div className="w-full h-full flex items-center justify-center relative overflow-hidden">
                <motion.div 
                    animate={{ backgroundColor: ["#991b1b", "#1e3a8a", "#991b1b"] }}
                    transition={{ duration: 0.5, repeat: Infinity }}
                    className="absolute inset-0 z-0 pointer-events-none opacity-50"
                />

                <motion.div 
                    className="relative z-10 bg-black border-4 border-red-600 p-8 md:p-12 rounded-lg max-w-2xl w-full text-center shadow-[0_0_50px_rgba(220,38,38,0.5)]"
                    initial={{ scale: 0.9 }}
                    animate={{ scale: [1, 1.02, 1] }}
                    transition={{ repeat: Infinity, duration: 0.2 }}
                >
                    <div className="mb-4">
                         <span className="text-6xl">🚨</span>
                    </div>
                    <h1 className="text-4xl md:text-6xl font-black text-red-500 mb-2 tracking-tighter" style={{ textShadow: '0 0 10px red' }}>
                        NOT ELIGIBLE
                    </h1>
                    <div className="text-3xl font-bold mb-6 text-red-200 font-mono">{percentage.toFixed(1)}%</div>

                    <p className="text-xl md:text-2xl text-white font-bold mb-8 uppercase font-mono leading-tight bg-red-900/30 p-4 rounded border border-red-500/30">
                        {roast}
                    </p>

                    <div className="space-y-4">
                        <button 
                            onClick={handleMedicalCertificate}
                            disabled={medicalStatus !== 'idle'}
                            className="bg-yellow-600 hover:bg-yellow-500 text-black font-bold py-4 px-8 rounded uppercase tracking-wider text-sm md:text-base w-full md:w-auto transition-all shadow-lg hover:shadow-yellow-500/50"
                        >
                            {medicalStatus === 'idle' && "Try with Medical Certificate"}
                            {medicalStatus === 'checking' && "Verifying Certificate..."}
                            {medicalStatus === 'rejected' && "❌ REJECTED"}
                        </button>

                        {medicalStatus === 'rejected' && (
                            <motion.div 
                                initial={{ opacity: 0, height: 0 }}
                                animate={{ opacity: 1, height: 'auto' }}
                                className="bg-red-900/50 p-2 rounded border border-red-500 text-red-200 font-mono text-sm"
                            >
                                SYSTEM REASON: {medicalRejectReason}
                            </motion.div>
                        )}
                    </div>
                </motion.div>

                <AnimatePresence>
                    {showFakeCall && (
                        <motion.div
                            initial={{ y: '100%' }}
                            animate={{ y: 0 }}
                            exit={{ y: '100%' }}
                            className="absolute bottom-0 left-0 right-0 bg-gray-900 border-t border-gray-700 p-6 z-50 flex items-center justify-between shadow-2xl"
                        >
                            {callStatus === 'incoming' ? (
                                <>
                                    <div className="flex items-center gap-4">
                                        <div className="w-14 h-14 bg-gray-700 rounded-full flex items-center justify-center text-2xl animate-pulse ring-4 ring-gray-600">
                                            📞
                                        </div>
                                        <div>
                                            <h4 className="text-white font-bold text-xl">HOD Calling...</h4>
                                            <p className="text-gray-400 text-sm">Mobile • +91 98XXX XXXXX</p>
                                        </div>
                                    </div>
                                    <div className="flex gap-6">
                                        <button onClick={() => setShowFakeCall(false)} className="flex flex-col items-center gap-1 group">
                                             <div className="w-14 h-14 rounded-full bg-red-500 flex items-center justify-center shadow-lg group-hover:bg-red-600 transition-colors">
                                                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                                                </svg>
                                             </div>
                                             <span className="text-xs text-gray-400">Decline</span>
                                        </button>
                                        <button onClick={answerCall} className="flex flex-col items-center gap-1 group">
                                            <div className="w-14 h-14 rounded-full bg-green-500 flex items-center justify-center animate-bounce shadow-lg group-hover:bg-green-600 transition-colors">
                                                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" />
                                                </svg>
                                            </div>
                                            <span className="text-xs text-gray-400">Answer</span>
                                        </button>
                                    </div>
                                </>
                            ) : (
                                <div className="w-full flex items-center justify-center py-4">
                                     <div className="text-center space-y-2">
                                        <h4 className="text-green-400 font-bold text-xl tracking-wide">CONNECTED 00:01</h4>
                                        <p className="text-white text-2xl font-black uppercase animate-pulse">
                                            "PLEASE MEET AFTER CLASS"
                                        </p>
                                     </div>
                                </div>
                            )}
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
         )}
       </motion.div>
    </AnimatePresence>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { GoogleGenAI, Modality } from '@google/genai';

interface Student {
  name: string;
  id: string;
  total: number;
  attended: number;
  pct: number;
  status: 'Safe' | 'Detained' | 'Topper';
}

interface TrollGameProps {
  isOpen: boolean;
  onClose: () => void;
}

const TEACHER_LINES = [
  "Establishing secure connection to Faculty Server...",
  "Opening physical attendance register [Year 2024-25]...",
  "Scanning biometric logs for matches...",
  "Cross-referencing WiFi authentication timestamps...",
  "Zooming into Corridor CCTV footage for verification...",
  "Analyzing 'Medical Leave' metadata...",
  "Finalizing shortage report for HOD review...",
  "Generating disciplinary action token..."
];

const EXCUSES = [
  { label: "Medical Emergency", result: "Rejected: Prescription date doesn't match bunk date." },
  { label: "Network Connectivity", result: "Rejected: You were seen online on Instagram during class." },
  { label: "Bus/Transport Breakdown", result: "Rejected: Tracking shows you were at the cafe nearby." },
  { label: "Dog Ate ID Card", result: "Rejected: Seriously? Come with parents tomorrow." }
];

// Audio decoding helpers
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const TrollGame: React.FC<TrollGameProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState<'form' | 'loading' | 'result' | 'game'>('form');
  const [isGroupMode, setIsGroupMode] = useState(false);
  const [students, setStudents] = useState<Student[]>([{ name: '', id: '', total: 0, attended: 0, pct: 0, status: 'Detained' }]);
  const [teacherMsgIndex, setTeacherMsgIndex] = useState(0);
  const [showFakeCall, setShowFakeCall] = useState(false);
  const [callStatus, setCallStatus] = useState<'incoming' | 'connected'>('incoming');
  const [selectedExcuse, setSelectedExcuse] = useState<string | null>(null);
  const [gameTime, setGameTime] = useState(10);
  const [gameState, setGameState] = useState<'idle' | 'playing' | 'won' | 'lost'>('idle');
  const [playerPosition, setPlayerPosition] = useState(50);
  const [assignments, setAssignments] = useState<{ id: number, x: number, y: number }[]>([]);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const activeSourcesRef = useRef<any[]>([]);

  const initAudio = () => {
    if (!audioCtxRef.current) {
      const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
      audioCtxRef.current = new AudioContextClass();
    }
    if (audioCtxRef.current?.state === 'suspended') audioCtxRef.current.resume();
  };

  const stopAllSounds = () => {
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch(e){} });
    activeSourcesRef.current = [];
  };

  const playHODVoice = async () => {
    initAudio();
    const ctx = audioCtxRef.current;
    if (!ctx) return;
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const mainStudent = students[0].name || 'Student';
      const prompt = `Say with deep anger: "${mainStudent}, I am looking at your attendance meter right now. It is pathetic. Your parents have been notified. Office. Now!"`;
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Charon' } } },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
        activeSourcesRef.current.push(source);
      }
    } catch (e) {}
  };

  const handleStartCheck = (e: React.FormEvent) => {
    e.preventDefault();
    initAudio();
    setStep('loading');
    setTeacherMsgIndex(0);
  };

  // Loading Logic
  useEffect(() => {
    if (step === 'loading') {
      const interval = setInterval(() => {
        setTeacherMsgIndex(prev => {
          if (prev >= TEACHER_LINES.length - 1) {
            clearInterval(interval);
            const updated = students.map(s => {
              const p = s.total === 0 ? 0 : (s.attended / s.total) * 100;
              return { ...s, pct: p, status: p > 90 ? 'Topper' : p >= 75 ? 'Safe' : 'Detained' };
            });
            setStudents(updated);
            setStep('result');
            if (updated.some(s => s.pct < 75)) {
               setTimeout(() => { setShowFakeCall(true); }, 4000);
            }
            return prev;
          }
          return prev + 1;
        });
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [step]);

  // Mini Game Logic
  useEffect(() => {
    if (gameState === 'playing') {
      const timer = setInterval(() => {
        setGameTime(prev => {
          if (prev <= 0) {
            clearInterval(timer);
            setGameState('won');
            return 0;
          }
          return prev - 1;
        });
      }, 1000);

      const spawner = setInterval(() => {
        setAssignments(prev => [...prev, { id: Date.now(), x: Math.random() * 90, y: -10 }]);
      }, 400);

      const physics = setInterval(() => {
        setAssignments(prev => {
           const next = prev.map(a => ({ ...a, y: a.y + 5 })).filter(a => a.y < 110);
           // Simple collision check
           const hit = next.find(a => a.y > 80 && a.y < 95 && Math.abs(a.x - playerPosition) < 10);
           if (hit) {
              setGameState('lost');
              clearInterval(timer);
              clearInterval(spawner);
              clearInterval(physics);
           }
           return next;
        });
      }, 50);

      return () => {
        clearInterval(timer);
        clearInterval(spawner);
        clearInterval(physics);
      };
    }
  }, [gameState, playerPosition]);

  const downloadReport = () => {
    alert("Generating encrypted PDF... Done!\n\nNOTICE: A copy of this report has been automatically sent to your registered parent's email address for immediate review. 📄📤");
  };

