                VERIFY ELIGIBILITY
              </button>
            </form>
          </motion.div>
        )}

        {step === 'loading' && (
          <div className="max-w-md w-full text-center space-y-8 p-8">
            <div className="relative inline-block">
              <div className="w-32 h-32 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin mx-auto"></div>
