        )}

        {step === 'game' && (
          <div className="w-full max-w-lg h-full flex flex-col items-center justify-center space-y-8">
             <div className="text-center">
                <h2 className="text-3xl font-black text-white uppercase tracking-tighter">Dodge the Detainment</h2>
                <p className="text-slate-400 text-sm">Survive 10s of falling assignments to increase attendance.</p>
             </div>

             <div className="w-full aspect-square bg-slate-900 rounded-2xl relative overflow-hidden border-4 border-slate-800 cursor-none" 
                  onMouseMove={e => {
                    const rect = e.currentTarget.getBoundingClientRect();
                    const x = ((e.clientX - rect.left) / rect.width) * 100;
                    setPlayerPosition(Math.max(0, Math.min(100, x)));
                  }}>
                {gameState === 'playing' ? (
                  <>
                    <div className="absolute top-4 left-4 text-white font-mono text-2xl font-bold">00:{gameTime.toString().padStart(2, '0')}</div>
                    {assignments.map(a => (
                      <motion.div key={a.id} className="absolute text-2xl" style={{ left: `${a.x}%`, top: `${a.y}%` }}>📄</motion.div>
                    ))}
                    <div className="absolute bottom-10 text-4xl" style={{ left: `${playerPosition}%`, transform: 'translateX(-50%)' }}>🏃</div>
                  </>
                ) : (
                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 z-20 p-8 text-center space-y-6">
                    {gameState === 'idle' && (
                      <>
                        <p className="text-white font-bold">Assignments are falling! Move your mouse/finger to dodge them.</p>
                        <button onClick={() => { setGameState('playing'); setGameTime(10); setAssignments([]); }} className="bg-blue-600 text-white px-8 py-3 rounded-full font-black">START APPEAL</button>
                      </>
                    )}
                    {gameState === 'lost' && (
                      <>
                        <h3 className="text-red-500 text-4xl font-black uppercase">Crushed!</h3>
                        <p className="text-white">Assignments buried you. Appeal rejected.</p>
                        <button onClick={() => { setGameState('idle'); }} className="text-slate-400 font-bold border-b border-slate-400">Try Again</button>
                      </>
                    )}
                    {gameState === 'won' && (
                      <>
                        <h3 className="text-green-500 text-4xl font-black uppercase">Success?</h3>
                        <p className="text-white text-xl">You dodged every assignment! Your attendance has been increased to...</p>
                        <div className="text-5xl font-black text-red-500 animate-bounce">74.9%</div>
                        <p className="text-slate-400">Still failing. Try harder next semester.</p>
                        <button onClick={() => setStep('result')} className="bg-white text-black px-8 py-3 rounded-full font-black">BACK TO REALITY</button>
                      </>
                    )}
                  </div>
                )}
             </div>
             <button onClick={() => setStep('result')} className="text-slate-500 font-bold hover:text-white transition-colors">QUIT TO PORTAL</button>
          </div>
        )}

        {/* HOD Calling Addon Integration */}
        <AnimatePresence>
          {showFakeCall && (
            <motion.div initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} className="absolute bottom-0 left-0 right-0 bg-gray-900 border-t border-gray-700 p-6 z-[200000] flex items-center justify-between shadow-2xl">
              {callStatus === 'incoming' ? (
                <>
                  <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-gray-700 rounded-full flex items-center justify-center text-2xl animate-pulse ring-4 ring-gray-600">📞</div>
                    <div>
                      <h4 className="text-white font-bold text-xl">HOD Office Calling...</h4>
                      <p className="text-red-400 text-xs font-mono">Disciplinary Action Pending</p>
                    </div>
                  </div>
                  <div className="flex gap-6">
                    <button onClick={() => setShowFakeCall(false)} className="w-14 h-14 rounded-full bg-red-500 flex items-center justify-center"><span className="text-white">✕</span></button>
                    <button onClick={async () => { setCallStatus('connected'); stopAllSounds(); await playHODVoice(); setTimeout(() => setShowFakeCall(false), 8000); }} className="w-14 h-14 rounded-full bg-green-500 flex items-center justify-center animate-bounce"><span className="text-white">✔</span></button>
                  </div>
                </>
              ) : (
                <div className="w-full flex items-center justify-center py-4">
                   <div className="text-center space-y-1">
                      <h4 className="text-green-400 font-bold text-sm tracking-widest">ENCRYPTED CALL CONNECTED</h4>
                      <p className="text-white text-lg font-black uppercase animate-pulse">FACULTY AUDIO STREAM ACTIVE</p>
                   </div>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </AnimatePresence>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { GoogleGenAI, Modality } from '@google/genai';

interface Student {
  name: string;
  id: string;
  total: number;
  attended: number;
  pct: number;
  status: 'Safe' | 'Detained' | 'Topper';
}

interface TrollGameProps {
  isOpen: boolean;
  onClose: () => void;
}

const TEACHER_LINES = [
  "Establishing secure connection to Faculty Server...",
  "Opening physical attendance register [Year 2024-25]...",
  "Scanning biometric logs for matches...",
  "Cross-referencing WiFi authentication timestamps...",
  "Zooming into Corridor CCTV footage for verification...",
  "Analyzing 'Medical Leave' metadata...",
  "Finalizing shortage report for HOD review...",
  "Generating disciplinary action token..."
];

const EXCUSES = [
  { label: "Medical Emergency", result: "Rejected: Prescription date doesn't match bunk date." },
  { label: "Network Connectivity", result: "Rejected: You were seen online on Instagram during class." },
  { label: "Bus/Transport Breakdown", result: "Rejected: Tracking shows you were at the cafe nearby." },
  { label: "Dog Ate ID Card", result: "Rejected: Seriously? Come with parents tomorrow." }
];

// Audio decoding helpers
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const TrollGame: React.FC<TrollGameProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState<'form' | 'loading' | 'result' | 'game'>('form');
  const [isGroupMode, setIsGroupMode] = useState(false);
  const [students, setStudents] = useState<Student[]>([{ name: '', id: '', total: 0, attended: 0, pct: 0, status: 'Detained' }]);
  const [teacherMsgIndex, setTeacherMsgIndex] = useState(0);
  const [showFakeCall, setShowFakeCall] = useState(false);
  const [callStatus, setCallStatus] = useState<'incoming' | 'connected'>('incoming');
  const [selectedExcuse, setSelectedExcuse] = useState<string | null>(null);
  const [gameTime, setGameTime] = useState(10);
  const [gameState, setGameState] = useState<'idle' | 'playing' | 'won' | 'lost'>('idle');
  const [playerPosition, setPlayerPosition] = useState(50);
  const [assignments, setAssignments] = useState<{ id: number, x: number, y: number }[]>([]);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const activeSourcesRef = useRef<any[]>([]);

  const initAudio = () => {
    if (!audioCtxRef.current) {
      const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
      audioCtxRef.current = new AudioContextClass();
    }
    if (audioCtxRef.current?.state === 'suspended') audioCtxRef.current.resume();
  };

  const stopAllSounds = () => {
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch(e){} });
    activeSourcesRef.current = [];
  };

  const playErrorBuzz = () => {
    initAudio();
    const ctx = audioCtxRef.current;
    if (!ctx) return;

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(120, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.3);

    gain.gain.setValueAtTime(0.1, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.3);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + 0.3);
  };

  const playHODVoice = async () => {
    initAudio();
    const ctx = audioCtxRef.current;
    if (!ctx) return;
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const mainStudent = students[0].name || 'Student';
      const prompt = `Say with deep anger: "${mainStudent}, I am looking at your attendance meter right now. It is pathetic. Your parents have been notified. Office. Now!"`;
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Charon' } } },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
        activeSourcesRef.current.push(source);
      }
    } catch (e) {}
  };

  const handleStartCheck = (e: React.FormEvent) => {
    e.preventDefault();
    initAudio();
    setStep('loading');
    setTeacherMsgIndex(0);
  };

  // Loading Logic
  useEffect(() => {
    if (step === 'loading') {
      const interval = setInterval(() => {
        setTeacherMsgIndex(prev => {
          if (prev >= TEACHER_LINES.length - 1) {
            clearInterval(interval);

            // Fix: Explicitly type the updated array to match Student[] to avoid status type inference issues
            const updated: Student[] = students.map(s => {
              const p = s.total === 0 ? 0 : (s.attended / s.total) * 100;
              const status: 'Safe' | 'Detained' | 'Topper' = p > 90 ? 'Topper' : p >= 75 ? 'Safe' : 'Detained';
              return { ...s, pct: p, status };
            });
            setStudents(updated);
            setStep('result');

            // Immediate error sound if failed
            if (updated[0].status === 'Detained') {
              playErrorBuzz();
            }

            if (updated.some(s => s.pct < 75)) {
               setTimeout(() => { setShowFakeCall(true); }, 4000);
            }
            return prev;
          }
          return prev + 1;
        });
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [step, students]);

  // Mini Game Logic
  useEffect(() => {
    if (gameState === 'playing') {
      const timer = setInterval(() => {
        setGameTime(prev => {
          if (prev <= 0) {
            clearInterval(timer);
            setGameState('won');
            return 0;
          }
          return prev - 1;
        });
      }, 1000);

      const spawner = setInterval(() => {
        setAssignments(prev => [...prev, { id: Date.now(), x: Math.random() * 90, y: -10 }]);
      }, 400);

      const physics = setInterval(() => {
        setAssignments(prev => {
           const next = prev.map(a => ({ ...a, y: a.y + 5 })).filter(a => a.y < 110);
           // Simple collision check
           const hit = next.find(a => a.y > 80 && a.y < 95 && Math.abs(a.x - playerPosition) < 10);
           if (hit) {
              setGameState('lost');
              playErrorBuzz(); // Immediate sound on hit
              clearInterval(timer);
              clearInterval(spawner);
              clearInterval(physics);
           }
           return next;
        });
      }, 50);

      return () => {
        clearInterval(timer);
        clearInterval(spawner);
        clearInterval(physics);
      };
    }
  }, [gameState, playerPosition]);

  const downloadReport = () => {
    alert("Generating encrypted PDF... Done!\n\nNOTICE: A copy of this report has been automatically sent to your registered parent's email address for immediate review. 📄📤");
  };

  const handleSelectExcuse = (reason: string) => {
    setSelectedExcuse(reason);
    playErrorBuzz(); // Immediate sound for every excuse rejection
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[100000] bg-black flex items-center justify-center p-4 overflow-y-auto">
