        {step === 'form' && (
          <motion.div initial={{ y: 20 }} animate={{ y: 0 }} className="bg-slate-50 rounded-xl shadow-2xl w-full max-w-lg overflow-hidden border-t-8 border-blue-900">
            <div className="bg-blue-900 p-6 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center font-bold text-blue-900 text-2xl border-2 border-yellow-500">U</div>
                <div>
                  <h2 className="text-white font-bold text-xl uppercase tracking-tighter">Imperial Central University</h2>
                  <p className="text-blue-300 text-[10px] font-mono">FACULTY OF DISCIPLINE & COMPLIANCE</p>
                </div>
              </div>
              <div className="text-right hidden sm:block">
                <div className="text-[10px] text-green-400 font-mono animate-pulse">● SERVER: ONLINE</div>
                <div className="text-[8px] text-blue-300 font-mono">LAST SYNC: JUST NOW</div>
              </div>
