                <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ delay: idx * 0.1 }} key={idx} className={`bg-white p-6 rounded-2xl shadow-xl border-b-8 ${s.status === 'Detained' ? 'border-red-600' : 'border-green-600'}`}>
