            </div>

            <div className="flex flex-col sm:flex-row gap-4 justify-center mt-12">
              <button onClick={downloadReport} className="bg-blue-900 text-white px-8 py-3 rounded-lg font-bold shadow-lg hover:bg-blue-800 transition-all">
