                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase">Attended</label>
                        <input required type="number" value={student.attended || ''} onChange={e => {
                          const n = [...students]; n[idx].attended = parseInt(e.target.value) || 0; setStudents(n);
                        }} className="w-full bg-slate-50 border border-slate-200 p-2 rounded text-sm text-black" placeholder="Attended" />
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {isGroupMode && (
                <button type="button" onClick={() => setStudents([...students, { name: '', id: '', total: 0, attended: 0, pct: 0, status: 'Detained' }])} className="w-full py-2 border-2 border-dashed border-slate-300 text-slate-500 text-xs font-bold hover:bg-slate-50 rounded">
                  + ADD CLASSMATE TO REPORT
