        {step === 'result' && (
          <div className="max-w-4xl w-full space-y-6 pb-20">
            <h1 className="text-white text-3xl font-black text-center mb-8 uppercase tracking-widest">Official Evaluation Results</h1>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map((s, idx) => (
                <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ delay: idx * 0.1 }} key={idx} className={`bg-white p-6 rounded-2xl shadow-xl border-b-8 ${s.status === 'Detained' ? 'border-red-600' : 'border-green-600'}`}>
                  <div className="flex justify-between items-start mb-4">
