            </div>

            {students.some(s => s.pct < 75) && (
              <div className="mt-8 p-6 bg-red-900/20 border border-red-500/50 rounded-xl">
                 <h4 className="text-red-500 font-bold mb-4 uppercase text-center text-sm">Submit Attendance Excuse</h4>
                 <div className="grid grid-cols-2 gap-4">
                    {EXCUSES.map(e => (
                      <button key={e.label} onClick={() => handleSelectExcuse(e.result)} className="p-3 bg-black/40 border border-slate-700 text-slate-300 text-[10px] rounded hover:border-red-500 transition-all">
                        {e.label}
                      </button>
                    ))}
                 </div>
                 {selectedExcuse && (
                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="mt-4 p-4 bg-red-600 text-white rounded font-mono text-[10px] font-bold">
                       SYSTEM ALERT: {selectedExcuse}
                    </motion.div>
                 )}
              </div>
            )}
          </div>
        )}

        {step === 'game' && (
          <div className="w-full max-w-lg h-full flex flex-col items-center justify-center space-y-8">
             <div className="text-center">
                <h2 className="text-3xl font-black text-white uppercase tracking-tighter">Dodge the Detainment</h2>
                <p className="text-slate-400 text-sm">Survive 10s of falling assignments to increase attendance.</p>
             </div>

             <div className="w-full aspect-square bg-slate-900 rounded-2xl relative overflow-hidden border-4 border-slate-800 cursor-none" 
                  onMouseMove={e => {
                    const rect = e.currentTarget.getBoundingClientRect();
                    const x = ((e.clientX - rect.left) / rect.width) * 100;
                    setPlayerPosition(Math.max(0, Math.min(100, x)));
                  }}>
                {gameState === 'playing' ? (
                  <>
                    <div className="absolute top-4 left-4 text-white font-mono text-2xl font-bold">00:{gameTime.toString().padStart(2, '0')}</div>
                    {assignments.map(a => (
                      <motion.div key={a.id} className="absolute text-2xl" style={{ left: `${a.x}%`, top: `${a.y}%` }}>📄</motion.div>
                    ))}
                    <div className="absolute bottom-10 text-4xl" style={{ left: `${playerPosition}%`, transform: 'translateX(-50%)' }}>🏃</div>
                  </>
                ) : (
                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 z-20 p-8 text-center space-y-6">
                    {gameState === 'idle' && (
                      <>
                        <p className="text-white font-bold">Assignments are falling! Move your mouse/finger to dodge them.</p>
                        <button onClick={() => { setGameState('playing'); setGameTime(10); setAssignments([]); }} className="bg-blue-600 text-white px-8 py-3 rounded-full font-black">START APPEAL</button>
                      </>
                    )}
                    {gameState === 'lost' && (
                      <>
                        <h3 className="text-red-500 text-4xl font-black uppercase">Crushed!</h3>
                        <p className="text-white">Assignments buried you. Appeal rejected.</p>
                        <button onClick={() => { setGameState('idle'); }} className="text-slate-400 font-bold border-b border-slate-400">Try Again</button>
                      </>
                    )}
                    {gameState === 'won' && (
                      <>
                        <h3 className="text-green-500 text-4xl font-black uppercase">Success?</h3>
                        <p className="text-white text-xl">You dodged every assignment! Your attendance has been increased to...</p>
                        <div className="text-5xl font-black text-red-500 animate-bounce">74.9%</div>
                        <p className="text-slate-400">Still failing. Try harder next semester.</p>
                        <button onClick={() => setStep('result')} className="bg-white text-black px-8 py-3 rounded-full font-black">BACK TO REALITY</button>
                      </>
                    )}
                  </div>
                )}
             </div>
             <button onClick={() => setStep('result')} className="text-slate-500 font-bold hover:text-white transition-colors">QUIT TO PORTAL</button>
          </div>
        )}

        <AnimatePresence>
          {showFakeCall && (
            <motion.div initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} className="absolute bottom-0 left-0 right-0 bg-gray-900 border-t border-gray-700 p-6 z-[200000] flex items-center justify-between shadow-2xl">
              {callStatus === 'incoming' ? (
                <>
                  <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-gray-700 rounded-full flex items-center justify-center text-2xl animate-pulse ring-4 ring-gray-600">📞</div>
                    <div>
                      <h4 className="text-white font-bold text-xl">HOD Office Calling...</h4>
                      <p className="text-red-400 text-xs font-mono">Disciplinary Action Pending</p>
                    </div>
                  </div>
                  <div className="flex gap-6">
                    <button onClick={() => setShowFakeCall(false)} className="w-14 h-14 rounded-full bg-red-500 flex items-center justify-center"><span className="text-white">✕</span></button>
                    <button onClick={async () => { setCallStatus('connected'); stopAllSounds(); await playHODVoice(); setTimeout(() => setShowFakeCall(false), 8000); }} className="w-14 h-14 rounded-full bg-green-500 flex items-center justify-center animate-bounce"><span className="text-white">✔</span></button>
                  </div>
                </>
              ) : (
                <div className="w-full flex items-center justify-center py-4">
                   <div className="text-center space-y-1">
                      <h4 className="text-green-400 font-bold text-sm tracking-widest">ENCRYPTED CALL CONNECTED</h4>
                      <p className="text-white text-lg font-black uppercase animate-pulse">FACULTY AUDIO STREAM ACTIVE</p>
                   </div>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </AnimatePresence>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { GoogleGenAI, Modality } from '@google/genai';

interface Student {
  name: string;
  id: string;
  total: number;
  attended: number;
  pct: number;
  status: 'Safe' | 'Detained' | 'Topper';
}

interface TrollGameProps {
  isOpen: boolean;
  onClose: () => void;
}

const TEACHER_LINES = [
  "Establishing secure connection to Faculty Server...",
  "Opening physical attendance register [Year 2024-25]...",
  "Scanning biometric logs for matches...",
  "Cross-referencing WiFi authentication timestamps...",
  "Zooming into Corridor CCTV footage for verification...",
  "Analyzing 'Medical Leave' metadata...",
  "Finalizing shortage report for HOD review...",
  "Generating disciplinary action token..."
];

const EXCUSES = [
  { label: "Medical Emergency", result: "Prescription date doesn't match bunk date." },
  { label: "Network Connectivity", result: "Rejected: You were seen online on Instagram during class." },
  { label: "Bus/Transport Breakdown", result: "Rejected: Tracking shows you were at the cafe nearby." },
  { label: "Dog Ate ID Card", result: "Rejected: Seriously? Come with parents tomorrow." }
];

// Audio decoding helpers
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const TrollGame: React.FC<TrollGameProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState<'form' | 'loading' | 'result' | 'game'>('form');
  const [isGroupMode, setIsGroupMode] = useState(false);
  const [students, setStudents] = useState<Student[]>([{ name: '', id: '', total: 0, attended: 0, pct: 0, status: 'Detained' }]);
  const [teacherMsgIndex, setTeacherMsgIndex] = useState(0);
  const [showFakeCall, setShowFakeCall] = useState(false);
  const [callStatus, setCallStatus] = useState<'incoming' | 'connected'>('incoming');
  const [selectedExcuse, setSelectedExcuse] = useState<string | null>(null);
  const [gameTime, setGameTime] = useState(10);
  const [gameState, setGameState] = useState<'idle' | 'playing' | 'won' | 'lost'>('idle');
  const [playerPosition, setPlayerPosition] = useState(50);
  const [assignments, setAssignments] = useState<{ id: number, x: number, y: number }[]>([]);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const activeSourcesRef = useRef<any[]>([]);
  const hasTriggeredDetentionVoice = useRef(false);

  // Pre-warm the audio context
  const initAudio = () => {
    if (!audioCtxRef.current) {
      const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
      audioCtxRef.current = new AudioContextClass();
    }
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  };

  const stopAllSounds = () => {
    activeSourcesRef.current.forEach(s => { try { s.stop(); } catch(e){} });
    activeSourcesRef.current = [];
  };

  // Immediate local sound (no latency)
  const playErrorBuzz = () => {
    initAudio();
    const ctx = audioCtxRef.current;
    if (!ctx) return;

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(150, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.35);

    gain.gain.setValueAtTime(0.15, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.35);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + 0.35);
  };

  // Background network sound (has latency, triggered early)
  const playSternVoice = async (text: string) => {
    initAudio();
    const ctx = audioCtxRef.current;
    if (!ctx) return;
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Say with extreme authority and a very stern tone: "${text}"` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Charon' } } },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
        activeSourcesRef.current.push(source);
      }
    } catch (e) {
      console.error("TTS failed", e);
    }
  };

  const playHODVoice = async () => {
    const mainStudent = students[0].name || 'Student';
    // Don't await, just fire and forget
    playSternVoice(`${mainStudent}, I am looking at your attendance meter right now. It is pathetic. Your parents have been notified. Meet me in my office immediately!`);
  };

  const handleStartCheck = (e: React.FormEvent) => {
    e.preventDefault();
    initAudio();
    setStep('loading');
    setTeacherMsgIndex(0);
    hasTriggeredDetentionVoice.current = false;
  };

  // Loading Logic with Early Voice Triggering
  useEffect(() => {
    if (step === 'loading') {
      const interval = setInterval(() => {
        setTeacherMsgIndex(prev => {
          // Early trigger: Start HOD Voice 1 step before finishing (approx 1s lead time)
          if (prev === TEACHER_LINES.length - 2 && !hasTriggeredDetentionVoice.current) {
            const mainPct = students[0].total === 0 ? 0 : (students[0].attended / students[0].total) * 100;
            if (mainPct < 75) {
              hasTriggeredDetentionVoice.current = true;
              playHODVoice(); // Start the network request early!
            }
          }

          if (prev >= TEACHER_LINES.length - 1) {
            clearInterval(interval);

            const updated: Student[] = students.map(s => {
              const p = s.total === 0 ? 0 : (s.attended / s.total) * 100;
              const status: 'Safe' | 'Detained' | 'Topper' = p > 90 ? 'Topper' : p >= 75 ? 'Safe' : 'Detained';
              return { ...s, pct: p, status };
            });
            setStudents(updated);
            setStep('result');

            if (updated[0].status === 'Detained') {
              playErrorBuzz(); // Instant local buzz
            }

            if (updated.some(s => s.pct < 75)) {
               setTimeout(() => { setShowFakeCall(true); }, 4000);
            }
            return prev;
          }
          return prev + 1;
        });
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [step, students]);

  // Mini Game Logic
  useEffect(() => {
    if (gameState === 'playing') {
      const timer = setInterval(() => {
        setGameTime(prev => {
          if (prev <= 0) {
            clearInterval(timer);
            setGameState('won');
            return 0;
          }
          return prev - 1;
        });
      }, 1000);

      const spawner = setInterval(() => {
        setAssignments(prev => [...prev, { id: Date.now(), x: Math.random() * 90, y: -10 }]);
      }, 400);

      const physics = setInterval(() => {
        setAssignments(prev => {
           const next = prev.map(a => ({ ...a, y: a.y + 5 })).filter(a => a.y < 110);
           const hit = next.find(a => a.y > 80 && a.y < 95 && Math.abs(a.x - playerPosition) < 10);
           if (hit) {
              setGameState('lost');
              playErrorBuzz(); // Instant local buzz
              clearInterval(timer);
              clearInterval(spawner);
              clearInterval(physics);
           }
           return next;
        });
      }, 50);

      return () => {
        clearInterval(timer);
        clearInterval(spawner);
        clearInterval(physics);
      };
    }
  }, [gameState, playerPosition]);

  const downloadReport = () => {
    alert("Generating encrypted PDF... Done!\n\nNOTICE: A copy of this report has been automatically sent to your registered parent's email address for immediate review. 📄📤");
  };

  const handleSelectExcuse = (reason: string) => {
    setSelectedExcuse(reason);
    playErrorBuzz(); // Immediate local buzz
    playSternVoice(`System Alert: ${reason}`); // Background network voice
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[100000] bg-black flex items-center justify-center p-4 overflow-y-auto">
        <button onClick={onClose} className="absolute top-4 right-4 text-white/30 hover:text-white z-50">✕ Close Portal</button>

        {step === 'form' && (
          <motion.div initial={{ y: 20 }} animate={{ y: 0 }} className="bg-slate-50 rounded-xl shadow-2xl w-full max-w-lg overflow-hidden border-t-8 border-blue-900">
            <div className="bg-blue-900 p-6 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center font-bold text-blue-900 text-2xl border-2 border-yellow-500">U</div>
                <div>
                  <h2 className="text-white font-bold text-xl uppercase tracking-tighter">Imperial Central University</h2>
                  <p className="text-blue-300 text-[10px] font-mono">FACULTY OF DISCIPLINE & COMPLIANCE</p>
                </div>
              </div>
              <div className="text-right hidden sm:block">
                <div className="text-[10px] text-green-400 font-mono animate-pulse">● SERVER: ONLINE</div>
                <div className="text-[8px] text-blue-300 font-mono">LAST SYNC: JUST NOW</div>
              </div>
            </div>

            <form onSubmit={handleStartCheck} className="p-6 space-y-6">
              <div className="flex justify-between items-center bg-blue-50 p-2 rounded-lg border border-blue-100">
                <span className="text-xs font-bold text-blue-900">GROUP EVALUATION MODE</span>
                <button type="button" onClick={() => setIsGroupMode(!isGroupMode)} className={`w-12 h-6 rounded-full transition-colors relative ${isGroupMode ? 'bg-blue-600' : 'bg-slate-300'}`}>
                   <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${isGroupMode ? 'left-7' : 'left-1'}`} />
                </button>
              </div>

              <div className="space-y-4 max-h-[40vh] overflow-y-auto pr-2 no-scrollbar">
                {students.map((student, idx) => (
                  <div key={idx} className="p-4 bg-white border border-slate-200 rounded-lg space-y-3 relative">
                    {idx > 0 && <button onClick={() => setStudents(students.filter((_, i) => i !== idx))} className="absolute top-2 right-2 text-red-500 text-xs font-bold">REMOVE</button>}
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase">Student Name</label>
                        <input required type="text" value={student.name} onChange={e => {
                          const n = [...students]; n[idx].name = e.target.value; setStudents(n);
                        }} className="w-full border-b-2 border-slate-300 py-1 focus:border-blue-900 outline-none text-sm text-black" placeholder="Full Name" />
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase">Student ID</label>
                        <input required type="text" value={student.id} onChange={e => {
                          const n = [...students]; n[idx].id = e.target.value; setStudents(n);
                        }} className="w-full border-b-2 border-slate-300 py-1 focus:border-blue-900 outline-none text-sm text-black" placeholder="ID: 2024XXX" />
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase">Total Slots</label>
                        <input required type="number" value={student.total || ''} onChange={e => {
                          const n = [...students]; n[idx].total = parseInt(e.target.value) || 0; setStudents(n);
                        }} className="w-full bg-slate-50 border border-slate-200 p-2 rounded text-sm text-black" placeholder="Total" />
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase">Attended</label>
                        <input required type="number" value={student.attended || ''} onChange={e => {
                          const n = [...students]; n[idx].attended = parseInt(e.target.value) || 0; setStudents(n);
                        }} className="w-full bg-slate-50 border border-slate-200 p-2 rounded text-sm text-black" placeholder="Attended" />
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {isGroupMode && (
                <button type="button" onClick={() => setStudents([...students, { name: '', id: '', total: 0, attended: 0, pct: 0, status: 'Detained' }])} className="w-full py-2 border-2 border-dashed border-slate-300 text-slate-500 text-xs font-bold hover:bg-slate-50 rounded">
                  + ADD CLASSMATE TO REPORT
                </button>
              )}

              <button type="submit" className="w-full bg-blue-900 text-white font-bold py-4 rounded shadow-xl hover:bg-blue-800 transition-all flex items-center justify-center gap-2">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                VERIFY ELIGIBILITY
              </button>
            </form>
          </motion.div>
        )}

        {step === 'loading' && (
          <div className="max-w-md w-full text-center space-y-8 p-8">
            <div className="relative inline-block">
              <div className="w-32 h-32 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin mx-auto"></div>
              <div className="absolute inset-0 flex items-center justify-center font-mono text-blue-500 font-bold">
                {Math.floor((teacherMsgIndex / TEACHER_LINES.length) * 100)}%
              </div>
            </div>
            <div className="space-y-4">
              <h2 className="text-white font-mono text-xl animate-pulse">FACULTY REVIEW SYSTEM</h2>
              <div className="bg-slate-900 p-4 rounded-lg border border-slate-700 text-left font-mono text-[10px] space-y-1">
                {TEACHER_LINES.slice(0, teacherMsgIndex + 1).map((line, i) => (
                  <div key={i} className="text-green-500">
                    <span className="opacity-50">[{new Date().toLocaleTimeString()}]</span> {line}
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {step === 'result' && (
          <div className="max-w-4xl w-full space-y-6 pb-20">
            <h1 className="text-white text-3xl font-black text-center mb-8 uppercase tracking-widest">Official Evaluation Results</h1>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map((s, idx) => (
                <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ delay: idx * 0.1 }} key={idx} className={`bg-white p-6 rounded-2xl shadow-xl border-b-8 ${s.status === 'Detained' ? 'border-red-600' : 'border-green-600'}`}>
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <h3 className="font-black text-slate-800 text-xl">{s.name || 'Anonymous'}</h3>
                      <p className="text-[10px] font-mono text-slate-400">ID: {s.id || 'N/A'}</p>
                    </div>
                    <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${s.status === 'Safe' ? 'bg-green-100 text-green-700' : s.status === 'Topper' ? 'bg-blue-100 text-blue-700' : 'bg-red-100 text-red-700'}`}>
                      {s.status}
                    </span>
                  </div>

                  <div className="space-y-2 mb-6">
                    <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase">
                      <span>Attendance Meter</span>
                      <span>{s.pct.toFixed(1)}%</span>
                    </div>
                    <div className="w-full h-4 bg-slate-100 rounded-full relative overflow-hidden">
                      <motion.div initial={{ width: 0 }} animate={{ width: `${s.pct}%` }} transition={{ duration: 1, ease: 'easeOut' }} className={`h-full ${s.pct < 75 ? 'bg-red-500' : 'bg-green-500'}`} />
                      <div className="absolute top-0 left-[75%] w-0.5 h-full bg-red-900 z-10 opacity-50" title="Safety Line (75%)" />
                    </div>
                  </div>

                  {s.status === 'Detained' && (
                    <div className="space-y-4">
                      <div className="p-3 bg-red-50 border border-red-100 rounded text-red-700 text-xs font-medium leading-tight italic">
                        "Your record indicates habitual absenteeism. Hall ticket generation has been suspended pending HOD interview."
                      </div>
                      <button onClick={() => setStep('game')} className="w-full py-2 bg-slate-900 text-white text-[10px] font-bold rounded uppercase hover:bg-black transition-colors">
                        Appeal to HOD (Mini-Game)
                      </button>
                    </div>
                  )}
                </motion.div>
              ))}
            </div>

            <div className="flex flex-col sm:flex-row gap-4 justify-center mt-12">
              <button onClick={downloadReport} className="bg-blue-900 text-white px-8 py-3 rounded-lg font-bold shadow-lg hover:bg-blue-800 transition-all">
                Download Official PDF Report
              </button>
              <button onClick={() => setStep('form')} className="bg-slate-200 text-slate-700 px-8 py-3 rounded-lg font-bold hover:bg-slate-300 transition-all">
                Check Another Student
              </button>
            </div>

            {students.some(s => s.pct < 75) && (
              <div className="mt-8 p-6 bg-red-900/20 border border-red-500/50 rounded-xl">
                 <h4 className="text-red-500 font-bold mb-4 uppercase text-center text-sm">Submit Attendance Excuse</h4>
                 <div className="grid grid-cols-2 gap-4">
                    {EXCUSES.map(e => (
                      <button key={e.label} onClick={() => handleSelectExcuse(e.result)} className="p-3 bg-black/40 border border-slate-700 text-slate-300 text-[10px] rounded hover:border-red-500 transition-all">
                        {e.label}
                      </button>
                    ))}
                 </div>
                 {selectedExcuse && (
                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="mt-4 p-4 bg-red-600 text-white rounded font-mono text-[10px] font-bold">
                       SYSTEM ALERT: {selectedExcuse}
                    </motion.div>
                 )}
              </div>
            )}
          </div>
        )}

        {step === 'game' && (
          <div className="w-full max-w-lg h-full flex flex-col items-center justify-center space-y-8">
             <div className="text-center">
                <h2 className="text-3xl font-black text-white uppercase tracking-tighter">Dodge the Detainment</h2>
                <p className="text-slate-400 text-sm">Survive 10s of falling assignments to increase attendance.</p>
             </div>

             <div className="w-full aspect-square bg-slate-900 rounded-2xl relative overflow-hidden border-4 border-slate-800 cursor-none" 
                  onMouseMove={e => {
                    const rect = e.currentTarget.getBoundingClientRect();
                    const x = ((e.clientX - rect.left) / rect.width) * 100;
                    setPlayerPosition(Math.max(0, Math.min(100, x)));
                  }}>
                {gameState === 'playing' ? (
                  <>
                    <div className="absolute top-4 left-4 text-white font-mono text-2xl font-bold">00:{gameTime.toString().padStart(2, '0')}</div>
                    {assignments.map(a => (
                      <motion.div key={a.id} className="absolute text-2xl" style={{ left: `${a.x}%`, top: `${a.y}%` }}>📄</motion.div>
                    ))}
                    <div className="absolute bottom-10 text-4xl" style={{ left: `${playerPosition}%`, transform: 'translateX(-50%)' }}>🏃</div>
                  </>
                ) : (
                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 z-20 p-8 text-center space-y-6">
                    {gameState === 'idle' && (
                      <>
                        <p className="text-white font-bold">Assignments are falling! Move your mouse/finger to dodge them.</p>
                        <button onClick={() => { setGameState('playing'); setGameTime(10); setAssignments([]); }} className="bg-blue-600 text-white px-8 py-3 rounded-full font-black">START APPEAL</button>
                      </>
                    )}
                    {gameState === 'lost' && (
                      <>
                        <h3 className="text-red-500 text-4xl font-black uppercase">Crushed!</h3>
                        <p className="text-white">Assignments buried you. Appeal rejected.</p>
                        <button onClick={() => { setGameState('idle'); }} className="text-slate-400 font-bold border-b border-slate-400">Try Again</button>
                      </>
                    )}
                    {gameState === 'won' && (
                      <>
                        <h3 className="text-green-500 text-4xl font-black uppercase">Success?</h3>
                        <p className="text-white text-xl">You dodged every assignment! Your attendance has been increased to...</p>
                        <div className="text-5xl font-black text-red-500 animate-bounce">74.9%</div>
                        <p className="text-slate-400">Still failing. Try harder next semester.</p>
                        <button onClick={() => setStep('result')} className="bg-white text-black px-8 py-3 rounded-full font-black">BACK TO REALITY</button>
                      </>
                    )}
                  </div>
                )}
             </div>
             <button onClick={() => setStep('result')} className="text-slate-500 font-bold hover:text-white transition-colors">QUIT TO PORTAL</button>
          </div>
        )}

        <AnimatePresence>
          {showFakeCall && (
            <motion.div initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} className="absolute bottom-0 left-0 right-0 bg-gray-900 border-t border-gray-700 p-6 z-[200000] flex items-center justify-between shadow-2xl">
              {callStatus === 'incoming' ? (
                <>
                  <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-gray-700 rounded-full flex items-center justify-center text-2xl animate-pulse ring-4 ring-gray-600">📞</div>
                    <div>
                      <h4 className="text-white font-bold text-xl">HOD Office Calling...</h4>
                      <p className="text-red-400 text-xs font-mono">Disciplinary Action Pending</p>
                    </div>
                  </div>
                  <div className="flex gap-6">
                    <button onClick={() => setShowFakeCall(false)} className="w-14 h-14 rounded-full bg-red-500 flex items-center justify-center"><span className="text-white">✕</span></button>
                    <button onClick={async () => { setCallStatus('connected'); stopAllSounds(); await playHODVoice(); setTimeout(() => setShowFakeCall(false), 8000); }} className="w-14 h-14 rounded-full bg-green-500 flex items-center justify-center animate-bounce"><span className="text-white">✔</span></button>
                  </div>
                </>
              ) : (
                <div className="w-full flex items-center justify-center py-4">
                   <div className="text-center space-y-1">
                      <h4 className="text-green-400 font-bold text-sm tracking-widest">ENCRYPTED CALL CONNECTED</h4>
                      <p className="text-white text-lg font-black uppercase animate-pulse">FACULTY AUDIO STREAM ACTIVE</p>
                   </div>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </AnimatePresence>
  );
}
